\label{lweightedtc}
For any finitely supported probability measure $\eta$ and any $s \in S$,
\[
\mathrm{TC}\big(\lambda_s\eta, \eta\big) \; \leq \;
\sum_{x \in G} |x| \, \big| \lambda_s\eta(x) - \eta(x) \big| .
\]
In particular, a group is transport amenable if there is a constant $K$ such that, for all $s \in S$ and all $n$,
\[\tag{$\star$}\label{ecritrelax}
\overset{}{\underset{x \in G}{\sum}} |x| \, \big|\delta_s * P^n(x) - P^n(x)\big| \; \leq \; K .
\]

\label{pentprofile}
Let $X = (V,E)$ be a graph and let $\mathcal{G}^{\scalebox{.4}{$\searrow$}}$ be its decreasing isoperimetric ratio function. For every finitely supported $f : V \to [0,1]$ with $\|f\|_{\ell^1V} = 1$,
\[
\|\nabla f\|_1 \; \geq \; \tfrac12 \sum_{x} f(x)\, \mathcal{G}^{\scalebox{.4}{$\searrow$}}\big(2/f(x)\big),
\]
the sum running over the support of $f$. Consequently:
\begin{enumerate}
\item[(a)] $\|\nabla f\|_1 \geq \tfrac14\, \mathcal{G}^{\scalebox{.4}{$\searrow$}}\big(2e^{2H(f)}\big)$;
\item[(b)] if $\psi : [0,\infty[ \, \to [0,\infty[$ is convex, non-increasing and satisfies $\psi(u) \leq \mathcal{G}^{\scalebox{.4}{$\searrow$}}(2e^u)$ for all $u \geq 0$, then $\|\nabla f\|_1 \geq \tfrac12\, \psi\big(H(f)\big)$.
\end{enumerate}

